import pandas as pd

def clean(df):
    df = df.copy()
    df['species'] = df['species'].str.capitalize().replace({'Gentto': 'Gentoo'})
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[df['flipper_length_mm'] >= 170]
    return df

def answer(df):
    df = clean(df)
    return df.groupby('species')['flipper_length_mm'].mean().to_dict()
